using BetaFit.Desktop.Forms;using BetaFit.Desktop.Helpers;using BetaFit.Desktop.Models;using BetaFit.Desktop.Services;
namespace BetaFit.Desktop.Controls;
public sealed class UcProducts:UserControl {private readonly IBetaFitApiService? _api;private readonly TextBox search=new();private readonly ComboBox category=new();private readonly DataGridView grid=new();private int page=1;public UcProducts():this(null){}public UcProducts(IBetaFitApiService? api){_api=api;Dock=DockStyle.Fill;BackColor=Color.FromArgb(15,18,23);Padding=new Padding(28);var bar=new Panel{Dock=DockStyle.Top,Height=55};search.PlaceholderText="Pesquisar produto...";search.Width=250;search.Location=new Point(0,12);category.Width=180;category.Location=new Point(265,11);category.DropDownStyle=ComboBoxStyle.DropDownList;var go=new Button{Text="Pesquisar",Location=new Point(455,10),Width=100};var add=new Button{Text="Novo produto",Location=new Point(565,10),Width=120};bar.Controls.AddRange(new Control[]{search,category,go,add});grid.Dock=DockStyle.Fill;FormHelper.StyleGrid(grid);Controls.Add(grid);Controls.Add(bar);if(_api!=null){go.Click+=async(_,_)=>{page=1;await LoadAsync();};add.Click+=async(_,_)=>await EditAsync(null);grid.CellDoubleClick+=async(_,e)=>{if(e.RowIndex>=0&&grid.Rows[e.RowIndex].Tag is ProductListItemResponse p)await EditAsync(p.Id);};Load+=async(_,_)=>{await CategoriesAsync();await LoadAsync();};var menu=new ContextMenuStrip();menu.Items.Add("Editar",null,async(_,_)=>{if(grid.CurrentRow?.Tag is ProductListItemResponse p)await EditAsync(p.Id);});menu.Items.Add("Ativar",null,async(_,_)=>await ActionAsync(_api.ActivateProductAsync));menu.Items.Add("Desativar",null,async(_,_)=>await ActionAsync(_api.DeactivateProductAsync));menu.Items.Add("Alternar destaque",null,async(_,_)=>{if(grid.CurrentRow?.Tag is ProductListItemResponse p)try{await _api.SetFeaturedAsync(p.Id,!p.IsFeatured);await LoadAsync();}catch(Exception x){Error(x);}});menu.Items.Add("Excluir",null,async(_,_)=>{if(grid.CurrentRow?.Tag is ProductListItemResponse p&&MessageBox.Show("Excluir este produto?","BetaFit",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)==DialogResult.Yes)try{await _api.DeleteProductAsync(p.Id);await LoadAsync();}catch(Exception x){Error(x);}});grid.ContextMenuStrip=menu;}}private async Task CategoriesAsync(){if(_api==null)return;var c=await _api.GetCategoriesAsync();category.DataSource=new[]{new CategoryResponse{Id=Guid.Empty,Name="Todas"}}.Concat(c).ToList();category.DisplayMember="Name";}private async Task LoadAsync(){if(_api==null)return;try{var c=(category.SelectedItem as CategoryResponse)?.Id;var r=await _api.SearchProductsAsync(search.Text,c==Guid.Empty?null:c,page,20);grid.Rows.Clear();grid.Columns.Clear();foreach(var h in new[]{"Nome","Categoria","Preço","Gênero","Status","Destaque"})grid.Columns.Add(h.ToLower(),h);foreach(var p in r.Items){var i=grid.Rows.Add(p.Name,p.CategoryName,p.Price.ToString("C2"),p.Gender switch{1=>"Masculino",2=>"Feminino",_=>"Unissex"},p.IsActive?"Ativo":"Inativo",p.IsFeatured?"Sim":"Não");grid.Rows[i].Tag=p;}}catch(Exception ex){Error(ex);}}private async Task EditAsync(Guid? id){if(_api==null)return;using var f=new FrmProductForm(_api,id);if(f.ShowDialog(FindForm())==DialogResult.OK)await LoadAsync();}private async Task ActionAsync(Func<Guid,Task> a){if(grid.CurrentRow?.Tag is ProductListItemResponse p)try{await a(p.Id);await LoadAsync();}catch(Exception x){Error(x);}}private static void Error(Exception e)=>MessageBox.Show(e.Message,"BetaFit",MessageBoxButtons.OK,MessageBoxIcon.Warning);}